export const insightsFa: Insight[] = faContent.map((localized) => {
  const original = insights.find((item) => item.slug === localized.slug);
  if (!original) throw new Error(`Missing English Insight for ${localized.slug}`);
  return { ...original, ...localized, sources: original.sources, related: original.related };
});

export const getInsightFa = (slug: string) => insightsFa.find((item) => item.slug === slug);
